//! Measurements for the Mago spike (design D11); the report is `docs/spikes/syntax-mago.md`.
//!
//! ```text
//! cargo run --release -p bleedthrough-syntax-mago --example spike -- [OPTIONS]
//!   --phase parse|full   which pipeline to time (default: both, in one process)
//!   --project DIR        also measure every .php file under DIR (read only, nothing is stored)
//!   --skip NAME          skip any path containing NAME (repeatable)
//!   --rounds N           timing rounds per input set (default 5; the median is reported)
//!   --generated BYTES    size of the generated file (default 8000000)
//!   --recovery           also run the mutation corpus and report regions made explicit
//! ```
//!
//! `parse` is Mago alone; `full` is the whole backend (thread, parse, conversion). Both run every
//! file on a scoped thread with the backend's stack size, so the thread cost is in both numbers and
//! the ratio isolates the conversion. Peak memory is the kernel's high-water mark for the process
//! (`VmHWM`), so run the phases in separate processes to compare them (see the report).

use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use bleedthrough_syntax::{
    ParseOptions, ParseQuality, ParserBackend, check_invariants, visit_tree,
};
use bleedthrough_syntax_conformance::Corpus;
use bleedthrough_syntax_conformance::mutate::{derive_seed, mutate};
use bleedthrough_syntax_mago::MagoBackend;
use mago_allocator::LocalArena;
use mago_database::file::FileId;
use mago_syntax::parser::parse_file_content_with_settings;
use mago_syntax::settings::{LexerSettings, ParserSettings};

const STACK: usize = 64 * 1024 * 1024;

struct Args {
    phase: Option<String>,
    project: Option<PathBuf>,
    skip: Vec<String>,
    rounds: usize,
    recovery: bool,
    generated: usize,
}

fn args() -> Args {
    let mut out = Args {
        phase: None,
        project: None,
        skip: vec![],
        rounds: 5,
        recovery: false,
        generated: 8_000_000,
    };
    let mut it = std::env::args().skip(1);
    while let Some(flag) = it.next() {
        match flag.as_str() {
            "--phase" => out.phase = it.next(),
            "--project" => out.project = it.next().map(PathBuf::from),
            "--skip" => out.skip.extend(it.next()),
            "--rounds" => out.rounds = it.next().and_then(|n| n.parse().ok()).unwrap_or(5),
            "--recovery" => out.recovery = true,
            "--generated" => {
                out.generated = it.next().and_then(|n| n.parse().ok()).unwrap_or(8_000_000)
            }
            other => panic!("unknown option {other}"),
        }
    }
    out
}

struct Input {
    name: String,
    bytes: Vec<u8>,
}

fn fixtures() -> Vec<Input> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/php");
    let corpus = Corpus::load(&root).expect("the corpus loads");
    corpus
        .fixtures
        .iter()
        .map(|f| Input {
            name: f.path.clone(),
            bytes: corpus.read(f).expect("readable"),
        })
        .collect()
}

/// A valid, deterministic file of roughly `target` bytes: the realistic fixtures wrapped in
/// namespaces and repeated.
fn generated(target: usize) -> Input {
    let parts: Vec<String> = fixtures()
        .into_iter()
        .filter(|f| f.name.starts_with("realistic/") && !f.name.contains("template"))
        .map(|f| {
            String::from_utf8_lossy(&f.bytes)
                .replace("<?php", "")
                .replace("declare(strict_types=1);", "")
        })
        .collect();
    let mut text = String::from("<?php\n");
    let mut n = 0;
    while text.len() < target {
        let body = &parts[n % parts.len()];
        let body = body.replace("namespace ", "// namespace ");
        text.push_str(&format!("namespace Gen\\N{n} {{\n{body}\n}}\n"));
        n += 1;
    }
    Input {
        name: format!("generated-{n}-blocks"),
        bytes: text.into_bytes(),
    }
}

fn project(dir: &Path, skip: &[String]) -> Vec<Input> {
    let mut out = Vec::new();
    let mut stack = vec![dir.to_path_buf()];
    while let Some(d) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&d) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            let shown = path.to_string_lossy().to_string();
            if skip.iter().any(|s| shown.contains(s)) {
                continue;
            }
            if path.is_dir() {
                stack.push(path);
            } else if path.extension().is_some_and(|e| e == "php")
                && let Ok(bytes) = std::fs::read(&path)
            {
                out.push(Input { name: shown, bytes });
            }
        }
    }
    out.sort_by(|a, b| a.name.cmp(&b.name));
    out
}

fn on_stack<T: Send>(work: impl FnOnce() -> T + Send) -> T {
    std::thread::scope(|scope| {
        std::thread::Builder::new()
            .stack_size(STACK)
            .spawn_scoped(scope, work)
            .expect("a thread can be spawned")
            .join()
            .expect("the work does not panic")
    })
}

fn mago_only(bytes: &[u8]) -> usize {
    on_stack(|| {
        let arena = LocalArena::new();
        let settings = ParserSettings {
            lexer: LexerSettings {
                enable_short_tags: false,
            },
            recover_incomplete: false,
        };
        let program = parse_file_content_with_settings(&arena, FileId::zero(), bytes, settings);
        program.errors.len()
    })
}

fn full(backend: &MagoBackend, bytes: &[u8]) -> usize {
    backend
        .parse("x.php", bytes, &ParseOptions::default())
        .diagnostics()
        .len()
}

fn median(mut v: Vec<Duration>) -> Duration {
    v.sort();
    v[v.len() / 2]
}

type Run<'a> = &'a dyn Fn(&[u8]) -> usize;

fn time_set(inputs: &[Input], rounds: usize, run: Run<'_>) -> Duration {
    let mut samples = Vec::new();
    for _ in 0..rounds {
        let started = Instant::now();
        let mut sink = 0;
        for input in inputs {
            sink += run(&input.bytes);
        }
        std::hint::black_box(sink);
        samples.push(started.elapsed());
    }
    median(samples)
}

fn peak_kib() -> String {
    std::fs::read_to_string("/proc/self/status")
        .ok()
        .and_then(|s| {
            s.lines()
                .find_map(|l| l.strip_prefix("VmHWM:").map(|v| v.trim().to_string()))
        })
        .unwrap_or_else(|| "unavailable".to_string())
}

fn report(label: &str, inputs: &[Input], args: &Args, backend: &MagoBackend) {
    let bytes: usize = inputs.iter().map(|i| i.bytes.len()).sum();
    let mb = bytes as f64 / 1_000_000.0;
    println!("== {label}: {} files, {mb:.2} MB", inputs.len());
    let mut parse = None;
    if args.phase.as_deref() != Some("full") {
        let t = time_set(inputs, args.rounds, &mago_only);
        println!(
            "  parse only         {:>9.1} ms  {:>7.1} MB/s",
            t.as_secs_f64() * 1e3,
            mb / t.as_secs_f64()
        );
        parse = Some(t);
    }
    if args.phase.as_deref() != Some("parse") {
        let t = time_set(inputs, args.rounds, &|b| full(backend, b));
        println!(
            "  parse + convert    {:>9.1} ms  {:>7.1} MB/s",
            t.as_secs_f64() * 1e3,
            mb / t.as_secs_f64()
        );
        if let Some(p) = parse {
            println!(
                "  ratio              {:>9.2}x  (limit 2.00x)",
                t.as_secs_f64() / p.as_secs_f64()
            );
        }
    }
    println!("  peak resident so far: {}", peak_kib());
}

#[derive(Default)]
struct Quality {
    clean: usize,
    recovered: usize,
    failed: usize,
    error_nodes: usize,
    unsupported: usize,
    diagnostics: usize,
}

fn quality(inputs: &[Input], backend: &MagoBackend) -> Quality {
    let mut q = Quality::default();
    for input in inputs {
        let parsed = backend.parse(&input.name, &input.bytes, &ParseOptions::default());
        match parsed.quality() {
            ParseQuality::Clean => q.clean += 1,
            ParseQuality::Failed => q.failed += 1,
            _ => q.recovered += 1,
        }
        q.error_nodes += parsed.error_count();
        q.unsupported += parsed.unsupported_count();
        q.diagnostics += parsed.diagnostics().len();
    }
    q
}

fn recovery(inputs: &[Input], backend: &MagoBackend) {
    let (mut files, mut violations, mut explicit, mut nodes) = (0, 0, 0, 0usize);
    for input in inputs.iter().filter(|i| !i.name.starts_with("malformed/")) {
        for index in 0..25 {
            let mutation = mutate(&input.bytes, derive_seed(0x0B1E_ED70, &input.name, index));
            let parsed = backend.parse(&input.name, &mutation.bytes, &ParseOptions::default());
            violations += check_invariants(parsed.tree(), &mutation.bytes).len();
            explicit += parsed.error_count() + parsed.unsupported_count();
            visit_tree(parsed.tree(), &mut |_| nodes += 1);
            files += 1;
        }
    }
    println!("== recovery on the mutation corpus");
    println!("  {files} mutated files, {nodes} nodes");
    println!("  invariant violations (uncovered bytes, overlaps, containment): {violations}");
    println!("  regions made explicit (error + unsupported nodes): {explicit}");
}

fn main() {
    let args = args();
    let backend = MagoBackend::new();
    let fixtures = fixtures();
    let large = vec![generated(args.generated)];
    println!("backend {:?}", backend.info());
    let q = quality(&fixtures, &backend);
    println!(
        "== fixture quality: {} clean, {} recovered, {} failed; {} error nodes, {} unsupported, {} diagnostics",
        q.clean, q.recovered, q.failed, q.error_nodes, q.unsupported, q.diagnostics
    );
    report("fixtures", &fixtures, &args, &backend);
    report(&large[0].name.clone(), &large, &args, &backend);
    if let Some(dir) = &args.project {
        let files = project(dir, &args.skip);
        let q = quality(&files, &backend);
        println!(
            "== project quality: {} clean, {} recovered, {} failed; {} error nodes, {} unsupported",
            q.clean, q.recovered, q.failed, q.error_nodes, q.unsupported
        );
        report("project", &files, &args, &backend);
    }
    if args.recovery {
        recovery(&fixtures, &backend);
    }
}
